// The top handler of the AI request's pump, which each panel's timer runs.
// An unexpected failure stops the request (ProviderAgent stops its own before
// throwing); the reply it was for ends failed and the chat can go on, or the
// title stays unmade. The failure goes to the report unchanged.
void AgentHost::pump_stream()
{
    const bool title = m_title.has_value();
    try {
        pump_agent();
    } catch (...) {
        if (!m_unexpected_error_handler)
            throw;
        m_unexpected_error_handler(title ? "making a chat's title" : "getting the AI's reply", std::current_exception());
        if (m_agent)
            m_agent->cancel();
        if (title)
            m_title.reset();
        else
            fail_stream(unexpected_error());
    }
    if (m_waiting_agent && !agent_busy()) {
        WaitingAgent waiting = std::move(*m_waiting_agent);
        set_agent(std::move(waiting.agent), waiting.availability);
    }
}

void AgentHost::pump_agent()
{
    if (m_title && m_handshake) {
        pump_conversation_title();
        return;
    }
    if (!m_stream || !m_handshake)
        return;

    const std::optional<AgentEvent> next = m_agent ? m_agent->poll() : std::nullopt;
    if (!next)
        return;

    if (next->kind == AgentEventKind::TextDelta) {
        const std::string& chunk = next->text;
        m_stream->message.text += chunk;
        m_persistence.document().update_message(m_stream->conversation_id, m_stream->message);
        m_persistence.commit();
        send_envelope(Protocol::kAssistantDelta,
                      json{{"messageId", m_stream->message.id}, {"seq", m_stream->next_seq++}, {"text", chunk}}.dump());
        return;
    }

    if (next->kind == AgentEventKind::ToolCall && next->tool)
        handle_agent_tool_call(*next->tool);
    else if (next->kind == AgentEventKind::Failed) {
        if (next->error && next->error->code == "invalid_credentials")
            note_key_rejected();
        fail_stream(next->error.value_or(AgentError{"agent_error", translated(L("The AI request failed.")), true}));
    }
    else if (next->kind == AgentEventKind::Completed)
        complete_stream();
}

