// The Agent page in its import mode (?panel=orca-import): the window Printer ›
// Import printers from OrcaSlicer… or Import printers from JusPrin 1… opens. It speaks
// the same bridge as Preferences; each button is a shell_action the window
// carries out (Home/OrcaImportWindow.cpp).

import { t } from '@lingui/core/macro';
import { useEffect, useMemo, useReducer } from 'react';
import { BridgeClient, Transport } from './bridge/client';
import { initialState, reducer } from './state/store';
import { applyAppearance } from './tokens';
import { BridgeErrorPane, ConnectingPane } from './components/Panels';
import { OrcaImport, OrcaImportActions } from './components/OrcaImport';

export function OrcaImportApp({ getTransport }: { getTransport: () => Transport | null }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  const client = useMemo(
    () =>
      new BridgeClient({
        getTransport,
        onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
        onEnvelope: (envelope) => dispatch({ kind: 'host', envelope }),
      }),
    // The transport is fixed for the lifetime of the page.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  useEffect(() => {
    client.start();
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  const actions = useMemo<OrcaImportActions>(
    () => ({
      importPrinters: (printers) => client.send('shell_action', { action: 'import', printers }),
      chooseFolder: () => client.send('shell_action', { action: 'choose_folder' }),
      close: () => client.send('shell_action', { action: 'close' }),
    }),
    [client],
  );

  if (state.connection !== 'connected' && state.connection !== 'connecting') {
    return (
      <div className="app">
        <BridgeErrorPane title={t`This window could not reach JusPrin`} detail={state.connectionDetail}
          diagnostics={state.diagnostics} onRetry={() => client.retry()} />
      </div>
    );
  }
  if (!state.orcaImport) return <div className="app"><ConnectingPane /></div>;

  return (
    <div className="app app--orca-import">
      <OrcaImport state={state.orcaImport} actions={actions} />
    </div>
  );
}
    afterPaint(action);
  };
  const folder = state.folder ?? '';
  const newPrinters = state.newPrinters ?? 0;
  const { app } = state;
  // Only the rows with the warning sign; the printers above them are fine.
  // Each of those rows says itself why JusPrin can't import it.
  const skipped = (state.skipped ?? []).length;

  let body;
  let buttons;
  switch (state.screen) {
    case 'imported':
      body = <Result app={app} result={state.result ?? []} />;
      buttons = <button type="button" className="primary" onClick={actions.close}>{t`Done`}</button>;
      break;
    case 'nothing_new':
      body = <>
        <p className="orca-import-lead">
          {skipped > 0
            ? plural(skipped, {
              1: `There is nothing to import. JusPrin already has everything in this ${app} folder except the item with the warning sign, which it can’t import.`,
              other: `There is nothing to import. JusPrin already has everything in this ${app} folder except the # items with the warning sign, which it can’t import.`
            })
            : t`Every printer in this ${app} folder is already in JusPrin, so there is nothing to import.`}
void OrcaImportWindow::choose_folder()
{
    const OrcaImporter::FolderChoice choice = m_importer.choose_folder(m_app, this);
    if (choice.folder) {
        m_error.clear();
        look(choice.folder);
    } else if (!choice.problem.empty()) {
        m_error = choice.problem;
    }
    m_view->host().refresh_page_state();
}

} // namespace Slic3r::GUI::JusPrin::Home
